PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    username TEXT UNIQUE NOT NULL,
    phone TEXT UNIQUE,
    display_name TEXT,
    password_hash TEXT NOT NULL,
    role TEXT NOT NULL DEFAULT 'member' CHECK (role IN ('admin', 'member', 'readonly')),
    must_change_password INTEGER DEFAULT 0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE audit_log (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER REFERENCES users(id),
    action TEXT NOT NULL,  -- login / logout / create / update / delete / import / export / change_password
    target TEXT,           -- 资源标识（lcsc_code 或 batch-时间戳 等）
    lib_type TEXT,         -- 操作的是哪个库（lcsc / standard / NULL）
    old_value TEXT,
    new_value TEXT,
    ip TEXT,
    user_agent TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE login_attempts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    username TEXT NOT NULL,
    ip TEXT NOT NULL,
    success INTEGER DEFAULT 0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS "material_library" (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    lib_type TEXT NOT NULL CHECK (lib_type IN ('lcsc', 'standard', 'cost')),
    sync_key TEXT NOT NULL,
    lcsc_code TEXT,
    name TEXT,
    model TEXT,
    specification TEXT,
    brand TEXT,
    material_code TEXT,
    package TEXT,
    category TEXT,
    manufacturer TEXT,
    unit TEXT,
    price TEXT,
    stock TEXT,
    datasheet TEXT,
    image_url TEXT,
    remark TEXT,
    source TEXT DEFAULT 'import' CHECK (source IN ('api', 'manual', 'import')),
    created_by INTEGER REFERENCES users(id),
    updated_by INTEGER REFERENCES users(id),
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (lib_type, sync_key)
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_audit_user ON audit_log(user_id);
CREATE INDEX idx_audit_created ON audit_log(created_at);
CREATE INDEX idx_login_username ON login_attempts(username);
CREATE INDEX idx_login_ip ON login_attempts(ip);
CREATE INDEX idx_material_libtype_key ON material_library(lib_type, sync_key);
CREATE INDEX idx_material_libtype_code ON material_library(lib_type, lcsc_code);
CREATE INDEX idx_material_libtype_updated ON material_library(lib_type, updated_at DESC);
CREATE INDEX idx_material_model ON material_library(model);
